<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/bootstrap.php'; require_admin();
$db = database_connection(); $notice = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf_token($_POST['csrf_token'] ?? null)) $error = 'This page expired. Refresh and try again.';
    elseif (($_POST['action'] ?? '') === 'add') {
        $name = trim((string)($_POST['name'] ?? '')); $email = strtolower(trim((string)($_POST['email'] ?? ''))); $specialty = trim((string)($_POST['specialty'] ?? ''));
        if ($name === '' || text_length($name) > 120 || filter_var($email,FILTER_VALIDATE_EMAIL) === false || $specialty === '' || text_length($specialty) > 100) $error = 'Enter a name, valid email, and specialty.';
        else { $q=$db->prepare('INSERT INTO experts (name,email,specialty) VALUES (:name,:email,:specialty)'); $q->execute(['name'=>$name,'email'=>$email,'specialty'=>$specialty]); $notice='Expert added.'; }
    } elseif (($_POST['action'] ?? '') === 'deactivate') {
        $id=(int)($_POST['id']??0); $q=$db->prepare('UPDATE experts SET active=0 WHERE id=:id'); $q->execute(['id'=>$id]); $notice='Expert removed from assignment lists.';
    }
}
$experts=$db->query('SELECT id,name,email,specialty,active FROM experts ORDER BY active DESC,name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Experts · You Aspirant admin</title><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="admin.css"><link rel="stylesheet" href="../features.css"></head><body class="admin-body"><header class="dashboard-header"><a class="admin-brand" href="/admin"><span class="brand-mark"><span>Y</span></span><span><strong>you aspirant</strong><small>Team directory</small></span></a><a class="logout-button" href="/admin">Inbox ↗</a></header><?php require __DIR__.'/_nav.php'; ?><main class="dashboard-main"><div class="dashboard-title"><div><p class="admin-eyebrow">Match support to student needs</p><h1>Experts</h1></div></div><?php if($notice):?><p class="admin-notice"><?=escape_html($notice)?></p><?php endif;?><?php if($error):?><p class="admin-error"><?=escape_html($error)?></p><?php endif;?><div class="admin-content-grid"><form class="feature-panel feature-form" method="post"><h2>Add an expert</h2><input type="hidden" name="csrf_token" value="<?=escape_html(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Name<input name="name" maxlength="120" required></label><label>Email<input name="email" type="email" maxlength="254" required></label><label>Specialty / services<input name="specialty" maxlength="100" placeholder="Career guidance, interview practice" required></label><button class="button button-dark" type="submit">Add expert ↗</button></form><section class="feature-panel"><h2>Team</h2><div class="admin-list"><?php foreach($experts as $expert):?><article><div><strong><?=escape_html($expert['name'])?></strong><small><?=escape_html($expert['email'])?> · <?=escape_html($expert['specialty'])?> · <?=$expert['active']?'Active':'Inactive'?></small></div><?php if($expert['active']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=escape_html(csrf_token())?>"><input type="hidden" name="action" value="deactivate"><input type="hidden" name="id" value="<?=(int)$expert['id']?>"><button class="row-action" type="submit">Deactivate</button></form><?php endif;?></article><?php endforeach;?></div></section></div></main></body></html>
